CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS websites(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,url text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,url));
CREATE TABLE IF NOT EXISTS risky_fonts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,family text NOT NULL,level text NOT NULL DEFAULT 'HIGH' CHECK(level IN('INFO','WARNING','HIGH','CRITICAL')),created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS risky_fonts_project_family_idx ON risky_fonts(project_id,lower(family));
CREATE TABLE IF NOT EXISTS scans(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),website_id uuid REFERENCES websites(id),status text NOT NULL CHECK(status IN('QUEUED','RUNNING','COMPLETED','FAILED','CANCELLED')),progress integer NOT NULL DEFAULT 0,debug_mode boolean NOT NULL DEFAULT false,max_pages integer NOT NULL,risky_fonts jsonb NOT NULL DEFAULT '[]',started_at timestamptz,finished_at timestamptz,duration_ms integer,error text,summary jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS pages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),scan_id uuid NOT NULL REFERENCES scans(id) ON DELETE CASCADE,url text NOT NULL,title text,screenshot_url text,duration_ms integer,status text NOT NULL DEFAULT 'COMPLETED',debug jsonb NOT NULL DEFAULT '{}',UNIQUE(scan_id,url));
CREATE TABLE IF NOT EXISTS typography_records(id bigserial PRIMARY KEY,page_id uuid NOT NULL REFERENCES pages(id) ON DELETE CASCADE,text_snippet text NOT NULL,tag text NOT NULL,xpath text NOT NULL,selector text NOT NULL,font_family text NOT NULL,font_size text,font_weight text,font_style text,line_height text,letter_spacing text,text_transform text,color text,font_stretch text,font_variation_settings text,fallback boolean NOT NULL DEFAULT false,visibility text,display text,risk_level text NOT NULL CHECK(risk_level IN('INFO','WARNING','HIGH','CRITICAL')));
CREATE INDEX IF NOT EXISTS typography_scan_font_idx ON typography_records(page_id,font_family);CREATE INDEX IF NOT EXISTS typography_selector_idx ON typography_records(selector);
CREATE TABLE IF NOT EXISTS discovered_fonts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),scan_id uuid NOT NULL REFERENCES scans(id) ON DELETE CASCADE,family text NOT NULL,occurrences integer NOT NULL,pages_used integer NOT NULL,elements integer NOT NULL,weights jsonb NOT NULL,styles jsonb NOT NULL,sources jsonb NOT NULL,usage_percentage numeric(7,4) NOT NULL,risk_level text NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS discovered_fonts_scan_family_idx ON discovered_fonts(scan_id,lower(family));
CREATE TABLE IF NOT EXISTS font_resources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),page_id uuid NOT NULL REFERENCES pages(id) ON DELETE CASCADE,url text NOT NULL,filename text,status integer,mime_type text,loaded boolean NOT NULL,failed boolean NOT NULL,duration_ms integer,cache_status text,response_headers jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS font_faces(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),page_id uuid NOT NULL REFERENCES pages(id) ON DELETE CASCADE,family text NOT NULL,weight text,style text,status text,loaded boolean,source text,display text);
CREATE TABLE IF NOT EXISTS debug_logs(id bigserial PRIMARY KEY,scan_id uuid NOT NULL REFERENCES scans(id) ON DELETE CASCADE,page_id uuid REFERENCES pages(id) ON DELETE CASCADE,level text NOT NULL,step text NOT NULL,message text NOT NULL,data jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),scan_id uuid NOT NULL REFERENCES scans(id) ON DELETE CASCADE,format text NOT NULL,object_url text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
